python3 - <<'EOF'
import shlex
cases = ["a#b", "'a'#b", '""#c', "a=b#c", "\\\\#", "a\\\\nb", '"a\\\\nb"', "abc\\", "#only comment", "x # y", "''", "a''b"]
for c in cases:
    try:
        print(repr(c), "->", shlex.split(c, comments=True))
    except ValueError as e:
        print(repr(c), "-> ERR:", e)
EOF

